<?php
if (!defined('ABSPATH')) { exit; }
final class KornSW_ATH_Introspector_Factory {
    public static function validate($profile,$access_token){$mode=(string)(($profile['AuthTokenConfig']??array())['ValidationMode']??'IMPLICIT_WHEN_USED');if($mode==='LOCAL_JWT_VALIDATION')return self::local_jwt_validate($profile,$access_token);$provider=KornSW_ATH_Provider_Registry::get_for_profile($profile);if(is_wp_error($provider))return array('technical_success'=>false,'active'=>false,'reason'=>$provider->get_error_message(),'claims'=>array());return $provider->validate_token($profile,$access_token);}
    public static function local_jwt_validate($profile,$token){$c=$profile['AuthTokenConfig']??array();$key=(string)($c['JwtValidationKey']??'');if($key==='')return array('technical_success'=>false,'active'=>false,'reason'=>'JwtValidationKey fehlt','claims'=>array());$p=explode('.',$token);if(count($p)!==3)return array('technical_success'=>true,'active'=>false,'reason'=>'Malformed JWT','claims'=>array());$header=json_decode(self::b64d($p[0]),true);$claims=json_decode(self::b64d($p[1]),true);if(!is_array($header)||!is_array($claims)||($header['alg']??'')!=='HS256')return array('technical_success'=>true,'active'=>false,'reason'=>'Unsupported JWT','claims'=>array());$expected=self::b64(hash_hmac('sha256',$p[0].'.'.$p[1],$key,true));if(!hash_equals($expected,$p[2]))return array('technical_success'=>true,'active'=>false,'reason'=>'Invalid JWT signature','claims'=>array());$now=time();if(isset($claims['exp'])&&(int)$claims['exp']<$now)return array('technical_success'=>true,'active'=>false,'reason'=>'expired','claims'=>$claims);if(isset($claims['nbf'])&&(int)$claims['nbf']>$now)return array('technical_success'=>true,'active'=>false,'reason'=>'not yet valid','claims'=>$claims);return array('technical_success'=>true,'active'=>true,'valid_until'=>isset($claims['exp'])?(int)$claims['exp']:null,'reason'=>null,'claims'=>$claims);}
    private static function b64d($v){$v=strtr($v,'-_','+/');$pad=strlen($v)%4;if($pad)$v.=str_repeat('=',4-$pad);return base64_decode($v);}
    private static function b64($v){return rtrim(strtr(base64_encode($v),'+/','-_'),'=');}
}
